# Let's try a constructive approach: start with a cycle of length 7
# and add edges one by one while maintaining girth >= 7.
# 22 vertices, 27 edges.

def construct():
    n = 22
    edges = set()
    # Start with a cycle of length 7
    cycle = [0, 1, 2, 3, 4, 5, 6]
    for i in range(7):
        u, v = cycle[i], cycle[(i+1)%7]
        if u > v: u, v = v, u
        edges.add((u, v))

    # Add more edges
    attempts = 0
    while len(edges) < 27 and attempts < 10000:
        u = random.randint(0, n-1)
        v = random.randint(0, n-1)
        if u == v: continue
        if u > v: u, v = v, u
        if (u, v) in edges: continue

        if get_girth(n, edges | {(u, v)}) >= 7:
            edges.add((u, v))
        attempts += 1

    if len(edges) >= 27:
        return list(edges)
    return None

